import type { ToolCallResult, UserQuestionData, UserQuestionOption } from '../types';

interface AgentCallbacks {
  onTextChunk: (text: string) => void;
  onThinkingDone: () => void;
  onToolCall: (pending: ToolCallResult) => void;
  onToolResult: (result: ToolCallResult) => void;
  onSubagentStart?: (data: { id: string; name: string; prompt: string }) => void;
  onSubagentEnd?: (data: { id: string; name: string; result?: string; sql_results?: Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>; chart_spec?: { data: unknown[]; layout?: Record<string, unknown> } }) => void;
  onDone: (sessionId: string | null) => void;
  onError: (error: string) => void;
  onUserQuestion?: (data: UserQuestionData) => void;
}

export type { AgentCallbacks };

async function streamSSE(
  response: Response,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
): Promise<void> {
  const reader = response.body?.getReader();
  if (!reader) {
    callbacks.onError('No response stream');
    return;
  }

  let doneReceived = false;
  const wrappedCallbacks: AgentCallbacks = {
    ...callbacks,
    onDone: (sessionId) => {
      doneReceived = true;
      callbacks.onDone(sessionId);
    },
    onError: (error) => {
      doneReceived = true;
      callbacks.onError(error);
    },
  };

  try {
    const decoder = new TextDecoder();
    let buffer = '';
    let eventType = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() ?? '';
      for (const line of lines) {
        if (line.startsWith('event: ')) {
          eventType = line.slice(7).trim();
        } else if (line.startsWith('data: ')) {
          const data = line.slice(6);
          try {
            const parsed = JSON.parse(data);
            handleSSEEvent(eventType, parsed, wrappedCallbacks);
          } catch {
            // Skip malformed JSON
          }
          eventType = '';
        }
      }
    }

    // Process any remaining data left in buffer after stream ends
    if (buffer.trim()) {
      const remainingLines = buffer.split('\n');
      for (const line of remainingLines) {
        if (line.startsWith('event: ')) {
          eventType = line.slice(7).trim();
        } else if (line.startsWith('data: ')) {
          const data = line.slice(6);
          try {
            const parsed = JSON.parse(data);
            handleSSEEvent(eventType, parsed, wrappedCallbacks);
          } catch {
            // Skip malformed JSON
          }
          eventType = '';
        }
      }
    }

    // Safety net: if stream ended without done/error, force done
    if (!doneReceived) {
      callbacks.onDone(null);
    }
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

export async function runAgentLoop(
  message: string,
  agentSessionId: string | null,
  langfuseSessionId: string | null,
  conversationHistory: { role: string; content: string }[] | null,
  conversationId?: string | null,
  callbacks?: AgentCallbacks,
  signal?: AbortSignal,
  userSessionId?: string,
  skills?: string[],
): Promise<void> {
  if (!callbacks) return;
  try {
    const response = await fetch('/api/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
      },
      body: JSON.stringify({
        message,
        session_id: agentSessionId,
        conversation_id: conversationId,
        langfuse_session_id: langfuseSessionId,
        conversation_history: conversationHistory ?? [],
        ...(skills?.length ? { skills } : {}),
      }),
      signal,
    });

    if (!response.ok) {
      const errorText = await response.text();
      callbacks.onError(`Server error: ${errorText}`);
      return;
    }

    await streamSSE(response, callbacks, signal);
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

export async function runAgentEditLoop(
  newMessage: string,
  conversationHistory: { role: string; content: string }[],
  langfuseSessionId: string | null,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
  userSessionId?: string,
  conversationId?: string | null,
): Promise<void> {
  try {
    const response = await fetch('/api/chat/edit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
      },
      body: JSON.stringify({
        new_message: newMessage,
        conversation_history: conversationHistory,
        langfuse_session_id: langfuseSessionId,
        conversation_id: conversationId,
      }),
      signal,
    });

    if (!response.ok) {
      const errorText = await response.text();
      callbacks.onError(`Server error: ${errorText}`);
      return;
    }

    await streamSSE(response, callbacks, signal);
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

function handleSSEEvent(
  eventType: string,
  data: Record<string, unknown>,
  callbacks: AgentCallbacks,
) {
  switch (eventType) {
    case 'thinking':
    case 'answer':
      callbacks.onTextChunk(data.text as string);
      break;
    case 'thinking_done':
      callbacks.onThinkingDone();
      break;
    case 'tool_call':
      callbacks.onToolCall({
        toolCallId: (data.id as string) ?? '',
        toolName: (data.name as string) ?? undefined,
        sql: (data.sql as string) ?? '',
        command: (data.command as string) ?? undefined,
        toolInput: (data.input as Record<string, unknown>) ?? undefined,
        columns: [],
        rows: [],
        rowCount: 0,
      });
      break;
    case 'tool_result': {
      const result: ToolCallResult = {
        toolCallId: (data.id as string) ?? '',
        toolName: (data.name as string) ?? undefined,
        sql: (data.sql as string) ?? '',
        columns: (data.columns as string[]) ?? [],
        rows: (data.rows as Record<string, unknown>[]) ?? [],
        rowCount: (data.rowCount as number) ?? 0,
        error: (data.error as string) ?? undefined,
        output: (data.output as string) ?? undefined,
        rawContent: (data.content as string) ?? undefined,
        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
      };
      callbacks.onToolResult(result);
      break;
    }
    case 'subagent_start':
      callbacks.onSubagentStart?.({
        id: data.id as string,
        name: data.name as string,
        prompt: (data.prompt as string) ?? '',
      });
      break;
    case 'subagent_end': {
      type ChartSpec = { data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[] };
      // Backend sends chart_specs (array) for multi-chart support.
      // Fall back to legacy chart_spec (single object) for backwards compat.
      const rawSpecs = data.chart_specs as ChartSpec[] | undefined;
      const legacySpec = data.chart_spec as ChartSpec | undefined;
      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);

      if (chartSpecs.length > 0) {
        // Emit one callback per chart so each gets its own segment
        for (const spec of chartSpecs) {
          callbacks.onSubagentEnd?.({
            id: data.id as string,
            name: data.name as string,
            chart_spec: spec,
          });
        }
        // Emit text result separately (if any) so it doesn't get lost
        if (data.result) {
          callbacks.onSubagentEnd?.({
            id: data.id as string,
            name: data.name as string,
            result: data.result as string,
          });
        }
      } else {
        callbacks.onSubagentEnd?.({
          id: data.id as string,
          name: data.name as string,
          result: (data.result as string) ?? undefined,
          sql_results: (data.sql_results as Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>) ?? undefined,
        });
      }
      break;
    }
    case 'user_question': {
      // Normalize options: the agent may send plain strings or {label, description} objects
      const rawOptions = (data.options as unknown[]) ?? [];
      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
        (opt: unknown) => {
          if (typeof opt === 'string') return { label: opt };
          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
          return { label: String(opt) };
        }
      );
      callbacks.onUserQuestion?.({
        questionId: data.question_id as string,
        question: data.question as string,
        options: normalizedOptions,
        multiSelect: (data.multi_select as boolean) ?? false,
      });
      break;
    }
    case 'done':
      callbacks.onDone((data.session_id as string) ?? null);
      break;
    case 'error':
      callbacks.onError((data.message as string) ?? 'Unknown error');
      break;
  }
}

import json
import logging
import anyio
from starlette.applications import Starlette
from starlette.requests import Request
from starlette.responses import Response
from starlette.routing import Route, Mount
from mcp.server.sse import SseServerTransport
from mcp.server.lowlevel.server import Server as MCPServer
import mcp.types as types
from app.session_manager import session_manager
from app.database import Database
from app.pending_questions import pending_question_store
import os
from app.skills import create_skill as _create_skill_file, SkillValidationError
from app.agent_memory import read_memories, save_memory, forget_memory

SKILLS_DIR = os.environ.get("SKILLS_DIR", os.path.join(os.path.dirname(__file__), "..", "..", "skills"))

logger = logging.getLogger(__name__)

MAX_RESULT_ROWS = 100

# The path here is relative to the Starlette app mount point (/mcp), not the
# full URL.  Starlette sets root_path=/mcp in the ASGI scope, and the MCP SDK
# prepends root_path when advertising the endpoint URL to clients.  Using
# "/messages/" avoids a double-prefix (/mcp/mcp/messages/).
sse_transport = SseServerTransport("/messages/")


def _create_mcp_server(db: Database, session_id: str) -> MCPServer:
    """Create a duckdb-data-agent MCP server with execute_sql, ask_user_question, and render_chart tools bound to a DuckDB instance."""
    server = MCPServer("duckdb-data-agent")

    @server.list_tools()
    async def list_tools() -> list[types.Tool]:
        return [
            types.Tool(
                name="execute_sql",
                description=(
                    "Execute a SQL query against the DuckDB database. "
                    "Results are returned as JSON with columns, rows, and rowCount."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {"sql": {"type": "string"}},
                    "required": ["sql"],
                },
            ),
            types.Tool(
                name="ask_user_question",
                description=(
                    "Ask the user a clarifying question with selectable options. "
                    "Pauses until the user responds."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "question": {"type": "string"},
                        "options": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "label": {"type": "string"},
                                    "description": {"type": "string"},
                                },
                                "required": ["label"],
                            },
                        },
                        "multi_select": {
                            "type": "boolean",
                            "default": False,
                            "description": (
                                "Set to true when the user should be able to pick more than one option "
                                "(e.g. 'which charts do you want?' or 'select all that apply'). "
                                "Defaults to false (single-select)."
                            ),
                        },
                    },
                    "required": ["question", "options"],
                },
            ),
            types.Tool(
                name="render_chart",
                description=(
                    "Render a Plotly chart. Call this as the final step after querying data. "
                    "Pass all Plotly traces in `data` and a layout object with a descriptive `title`."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "data": {
                            "type": "array",
                            "description": "Array of Plotly trace objects (bar, line, scatter, pie, etc.)",
                            "items": {"type": "object"},
                        },
                        "layout": {
                            "type": "object",
                            "description": "Plotly layout object",
                            "properties": {
                                "title": {"type": "string"},
                            },
                            "required": ["title"],
                        },
                    },
                    "required": ["data", "layout"],
                },
            ),
            types.Tool(
                name="create_skill",
                description=(
                    "Create a reusable skill (workflow template) that can be invoked later. "
                    "The skill is saved as a SKILL.md file and becomes available via /skill-name."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "name": {
                            "type": "string",
                            "description": "Skill identifier in hyphen-case (e.g. 'my-analysis-workflow')",
                        },
                        "description": {
                            "type": "string",
                            "description": "What the skill does and when to use it (max 1024 chars)",
                        },
                        "content": {
                            "type": "string",
                            "description": "Full markdown body with step-by-step instructions",
                        },
                    },
                    "required": ["name", "description", "content"],
                },
            ),
            types.Tool(
                name="save_memory",
                description=(
                    "Save a piece of information to long-term memory so it persists across conversations. "
                    "Use this to remember user preferences, important facts, or recurring patterns."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "content": {
                            "type": "string",
                            "description": "The memory content to save (e.g. 'User prefers bar charts')",
                        },
                        "category": {
                            "type": "string",
                            "enum": ["preference", "fact", "pattern"],
                            "description": "Category of the memory: preference (user likes/dislikes), fact (important information), or pattern (recurring behavior)",
                        },
                    },
                    "required": ["content", "category"],
                },
            ),
            types.Tool(
                name="recall_memories",
                description=(
                    "Recall all saved memories, optionally filtered by a keyword query. "
                    "Use this at the start of a conversation to check for relevant context."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "query": {
                            "type": "string",
                            "description": "Optional keyword to filter memories (case-insensitive substring match)",
                        },
                    },
                },
            ),
            types.Tool(
                name="forget_memory",
                description=(
                    "Remove a specific memory entry. The content must match an existing memory exactly."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "content": {
                            "type": "string",
                            "description": "The exact memory content to forget (without the leading '- ')",
                        },
                    },
                    "required": ["content"],
                },
            ),
        ]

    @server.call_tool()
    async def call_tool(
        name: str, arguments: dict
    ) -> list[types.TextContent]:
        if name == "execute_sql":
            sql = arguments.get("sql", "")
            try:
                result = await db.execute_query_async(sql)
                truncated_rows = result["rows"][:MAX_RESULT_ROWS]
                result_json = {
                    "status": "success",
                    "columns": result["columns"],
                    "rows": truncated_rows,
                    "rowCount": result["rowCount"],
                }
                return [types.TextContent(type="text", text=json.dumps(result_json, default=str))]
            except Exception as e:
                error_json = {"status": "error", "error": str(e)}
                return [types.TextContent(type="text", text=json.dumps(error_json))]
        elif name == "ask_user_question":
            question_data = {
                "question": arguments.get("question", ""),
                "options": arguments.get("options", []),
                "multi_select": arguments.get("multi_select", False),
            }
            question_id = pending_question_store.create(session_id, question_data)
            answer = await pending_question_store.wait(session_id, question_id, timeout=300.0)
            if answer is None:
                result = {"timeout": True, "message": "User did not respond within the time limit."}
            else:
                result = answer
            return [types.TextContent(type="text", text=json.dumps(result))]
        elif name == "render_chart":
            data = arguments.get("data")
            layout = arguments.get("layout", {})
            if not isinstance(data, list):
                logger.warning("render_chart called with missing data: %s", arguments)
                return [types.TextContent(type="text", text=json.dumps({"status": "error", "error": "data (array of Plotly traces) is required"}))]

            # Reject specs where every trace has empty data arrays.
            # Data-bearing fields vary by chart type (x, y, z, values, labels, etc.).
            _DATA_FIELDS = ("x", "y", "z", "values", "labels", "lat", "lon", "r", "theta",
                            "lowerfence", "q1", "median", "q3", "upperfence")
            has_nonempty_trace = False
            for trace in data:
                if not isinstance(trace, dict):
                    continue
                for field in _DATA_FIELDS:
                    val = trace.get(field)
                    if isinstance(val, list) and len(val) > 0:
                        has_nonempty_trace = True
                        break
                if has_nonempty_trace:
                    break
            if not has_nonempty_trace:
                logger.warning("render_chart called with all-empty data traces: %s", arguments)
                return [types.TextContent(type="text", text=json.dumps({
                    "status": "error",
                    "error": "All data traces are empty — no data to chart. "
                             "Check your SQL query results before calling render_chart."
                }))]
            # Return success with chart_spec so the orchestrator can see
            # what was rendered and write coherent commentary about it.
            return [types.TextContent(type="text", text=json.dumps({
                "status": "success",
                "chart_spec": {"data": data, "layout": layout},
            }))]
        elif name == "create_skill":
            skill_name = arguments.get("name", "")
            description = arguments.get("description", "")
            content = arguments.get("content", "")
            try:
                _create_skill_file(skill_name, description, content, SKILLS_DIR)
                return [types.TextContent(type="text", text=json.dumps({
                    "success": True,
                    "message": f"Skill '{skill_name}' created successfully. Users can now invoke it with /{skill_name}.",
                }))]
            except SkillValidationError as e:
                return [types.TextContent(type="text", text=json.dumps({
                    "success": False,
                    "error": str(e),
                }))]
        elif name == "save_memory":
            content = arguments.get("content", "")
            category = arguments.get("category", "fact")
            result = save_memory(content, category)
            return [types.TextContent(type="text", text=json.dumps({"status": "success", "message": result}))]
        elif name == "recall_memories":
            query = arguments.get("query", "")
            memories = read_memories()
            if query and memories:
                query_lower = query.lower()
                lines = memories.split("\n")
                result_lines: list[str] = []
                current_header: str | None = None
                section_entries: list[str] = []
                for line in lines:
                    if line.startswith("# "):
                        # Top-level header always included
                        if current_header and section_entries:
                            result_lines.append(current_header)
                            result_lines.append("")
                            result_lines.extend(section_entries)
                            result_lines.append("")
                        current_header = None
                        section_entries = []
                        result_lines.append(line)
                        result_lines.append("")
                    elif line.startswith("## "):
                        # Flush previous section if it had matches
                        if current_header and section_entries:
                            result_lines.append(current_header)
                            result_lines.append("")
                            result_lines.extend(section_entries)
                            result_lines.append("")
                        current_header = line
                        section_entries = []
                    elif line.startswith("- ") and query_lower in line.lower():
                        section_entries.append(line)
                # Flush last section
                if current_header and section_entries:
                    result_lines.append(current_header)
                    result_lines.append("")
                    result_lines.extend(section_entries)
                    result_lines.append("")
                memories = "\n".join(result_lines).strip()
            return [types.TextContent(type="text", text=json.dumps({"status": "success", "memories": memories}))]
        elif name == "forget_memory":
            content = arguments.get("content", "")
            result = forget_memory(content)
            return [types.TextContent(type="text", text=json.dumps({"status": "success", "message": result}))]
        else:
            raise ValueError(f"Unknown tool: {name}")

    return server


async def handle_sse(request: Request) -> Response:
    """Handle SSE connection. Requires session_id query param."""
    session_id = request.query_params.get("session_id")
    if not session_id:
        return Response("session_id query parameter is required", status_code=400)

    db = session_manager.get_or_create(session_id)
    server = _create_mcp_server(db, session_id)

    try:
        async with sse_transport.connect_sse(
            request.scope, request.receive, request._send
        ) as streams:
            await server.run(
                streams[0],
                streams[1],
                server.create_initialization_options(),
            )
    except anyio.ClosedResourceError:
        logger.debug("MCP SSE client disconnected (session %s)", session_id)
    except BaseExceptionGroup as eg:
        # The MCP library uses anyio task groups which wrap errors in
        # ExceptionGroups.  Filter out ClosedResourceError (normal client
        # disconnect) and re-raise anything else.
        _, rest = eg.split(anyio.ClosedResourceError)
        if rest:
            raise rest from None
        logger.debug("MCP SSE client disconnected (session %s)", session_id)

    return Response()


mcp_app = Starlette(
    routes=[
        Route("/sse", endpoint=handle_sse, methods=["GET"]),
        Mount("/messages/", app=sse_transport.handle_post_message),
    ]
)

