186→function handleSSEEvent(
187→  eventType: string,
188→  data: Record<string, unknown>,
189→  callbacks: AgentCallbacks,
190→) {
191→  switch (eventType) {
192→    case 'thinking':
193→    case 'answer':
194→      callbacks.onTextChunk(data.text as string);
195→      break;
196→    case 'thinking_done':
197→      callbacks.onThinkingDone();
198→      break;
199→    case 'tool_call':
200→      callbacks.onToolCall({
201→        toolCallId: (data.id as string) ?? '',
202→        toolName: (data.name as string) ?? undefined,
203→        sql: (data.sql as string) ?? '',
204→        command: (data.command as string) ?? undefined,
205→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
206→        columns: [],
207→        rows: [],
208→        rowCount: 0,
209→      });
210→      break;
211→    case 'tool_result': {
212→      const result: ToolCallResult = {
213→        toolCallId: (data.id as string) ?? '',
214→        toolName: (data.name as string) ?? undefined,
215→        sql: (data.sql as string) ?? '',
216→        columns: (data.columns as string[]) ?? [],
217→        rows: (data.rows as Record<string, unknown>[]) ?? [],
218→        rowCount: (data.rowCount as number) ?? 0,
219→        error: (data.error as string) ?? undefined,
220→        output: (data.output as string) ?? undefined,
221→        rawContent: (data.content as string) ?? undefined,
222→        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
223→      };
224→      callbacks.onToolResult(result);
225→      break;
226→    }
227→    case 'subagent_start':
228→      callbacks.onSubagentStart?.({
229→        id: data.id as string,
230→        name: data.name as string,
231→        prompt: (data.prompt as string) ?? '',
232→      });
233→      break;
234→    case 'subagent_end': {
235→      type ChartSpec = { data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[] };
236→      // Backend sends chart_specs (array) for multi-chart support.
237→      // Fall back to legacy chart_spec (single object) for backwards compat.
238→      const rawSpecs = data.chart_specs as ChartSpec[] | undefined;
239→      const legacySpec = data.chart_spec as ChartSpec | undefined;
240→      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);
241→
242→      if (chartSpecs.length > 0) {
243→        // Emit one callback per chart so each gets its own segment
244→        for (const spec of chartSpecs) {
245→          callbacks.onSubagentEnd?.({
246→            id: data.id as string,
247→            name: data.name as string,
248→            chart_spec: spec,
249→          });
250→        }
251→        // Emit text result separately (if any) so it doesn't get lost
252→        if (data.result) {
253→          callbacks.onSubagentEnd?.({
254→            id: data.id as string,
255→            name: data.name as string,
256→            result: data.result as string,
257→          });
258→        }
259→      } else {
260→        callbacks.onSubagentEnd?.({
261→          id: data.id as string,
262→          name: data.name as string,
263→          result: (data.result as string) ?? undefined,
264→          sql_results: (data.sql_results as Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>) ?? undefined,
265→        });
266→      }
267→      break;
268→    }
269→    case 'user_question': {
270→      // Normalize options: the agent may send plain strings or {label, description} objects
271→      const rawOptions = (data.options as unknown[]) ?? [];
272→      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
273→        (opt: unknown) => {
274→          if (typeof opt === 'string') return { label: opt };
275→          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
276→          return { label: String(opt) };
277→        }
278→      );
279→      callbacks.onUserQuestion?.({
280→        questionId: data.question_id as string,
281→        question: data.question as string,
282→        options: normalizedOptions,
283→        multiSelect: (data.multi_select as boolean) ?? false,
284→      });
285→      break;
286→    }
287→    case 'done':
288→      callbacks.onDone((data.session_id as string) ?? null);
289→      break;
290→    case 'error':
291→      callbacks.onError((data.message as string) ?? 'Unknown error');
292→      break;
293→  }
294→}
